const errorRaw = $json.error ?? $json.errorMessage ?? '';
const errorText = typeof errorRaw === 'string'
  ? errorRaw.trim()
  : String(errorRaw?.description ?? errorRaw?.message ?? '').trim();
const salida = String($json.output ?? $json.text ?? '').trim();
const proveedorFallo = /429|quota|cuota|rate limit|too many requests|503|service unavailable|high demand|saturad/i.test(`${errorText} ${salida}`);
return [{ json: {
  ...$json,
  necesita_respaldo: Boolean(errorText || !salida || proveedorFallo),
  respuesta_primaria: salida
} }];

const errorRaw = $json.error ?? $json.errorMessage ?? '';
const errorText = typeof errorRaw === 'string'
  ? errorRaw.trim()
  : String(errorRaw?.description ?? errorRaw?.message ?? '').trim();
let respuesta = String($json.output ?? $json.respuesta_primaria ?? $json.text ?? '').trim();
if (errorText || !respuesta || /429|quota|cuota|rate limit|too many requests|503|service unavailable|high demand|saturad/i.test(`${errorText} ${respuesta}`)) {
  respuesta = 'En este momento estoy con mucha demanda y no pude procesar bien tu mensaje. No voy a inventar datos ni confirmar pagos: reenviámelo en unos minutos, por favor.';
}
if (/^calling\s+|\$fromAI|default_api:/i.test(respuesta)) {
  respuesta = 'Tu pedido no llegó en un formato válido. Repetímelo una vez y lo reviso sin asumir ningún dato.';
}
return [{ json: { respuesta_cliente: respuesta.slice(0, 3800) } }];
